head.script:
scwin.onpageload = function() {
    //dataMap1.setJSON({"key1":"2019-12-18 10:10"});
    dataMap1.setJSON({
        "key1": "201912300910"
    }); //2019-12-30 09:10
};
scwin.onpageunload = function() {};
scwin.inputCalendar1_onviewchange = function(info) {
    console.log("inputCalendar1: ", info);
};
scwin.gridView1_onviewchange = function(info) {
    console.log("gridView1: ", info);
};
scwin.gridView1_oncellindexchange = function(row, col, oldRow, oldCol) {
    console.log("gridView1_oncellindexchange: ", row, col, oldRow, oldCol);
    var colID = gridView1.getColumnID(col);
    if (colID == "col1") {
        gridView1.setFocusedCell(row, col, false);
    }
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /**
     * 2019-08-06 11:12 처럼 포맷된 형태의 값을 복사붙여넣기 시 inputCalendar onviewchange 이벤트 발생안함.
     * 201908061122 처럼 포맷되지 않은 데이터를 붙여넣기한 직후에는 위 값을 붙여넣어도 onviewchange 발생함.
     */
    /**
     * IE에서 탭으로 이동 시 포맷값 유지됨.
     * dataDragSelect=true 이면 IE에서 셀 클릭 시 포맷값 유지됨.
     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
